typedef enum { LOCKED, UNLOCKED, ALARM } lock_t;
lock_t s = LOCKED;
int wrong = 0;

void on_event(char e) {
    switch (s) {
    case LOCKED:
        if (e == 'C') { s = UNLOCKED; wrong = 0; }
        else if (e == 'W' && ++wrong >= 3) s = ALARM;
        break;
    case UNLOCKED:
        if (e == 'L') s = LOCKED;
        break;
    case ALARM:
        if (e == 'R') { s = LOCKED; wrong = 0; }
        break;
    }
}

